// FPGA top level for the Digilent Nexys A7 (generated by LSE)
// Use together with the matching .xdc file (pin numbers).
//   inputs  -> switches  (a=SW[2], b=SW[1], cin=SW[0])
//   outputs -> LEDs      (sum=LED[0], cout=LED[1])
//   7-seg   -> off
`timescale 1ns / 1ps

module top (
    input  wire [15:0] SW,
    output wire [15:0] LED,
    output wire        CA, CB, CC, CD, CE, CF, CG,   // segment cathodes, active low
    output wire        DP,                           // decimal point, active low
    output wire [7:0]  AN                            // digit enables, active low
);
    wire [1:0] y;   // outputs of the generated logic

    full_adder core (
        .a(SW[2]),
        .b(SW[1]),
        .cin(SW[0]),
        .sum(y[0]),
        .cout(y[1])
    );

    assign LED = {14'b0, y};
    assign {CG, CF, CE, CD, CC, CB, CA} = 7'h7F;     // segments off
    assign AN = 8'hFF;                                // all digits off
    assign DP = 1'b1;                                  // decimal point off
endmodule

// Structural Verilog generated by LSE (Logic Synthesis Engine)
// Design: full_adder   inputs: a b cin   style: AND-OR
//   sum = a*b*cin + a*b'*cin' + a'*b*cin' + a'*b'*cin
//   cout = a*b + a*cin + b*cin
// Gates: 12  transistors: 74  levels: 3  delay: 6.25 tau
`timescale 1ns / 1ps

module full_adder (
    input  wire a,
    input  wire b,
    input  wire cin,
    output wire sum,
    output wire cout
);

    wire w0, b_n, cin_n, w3, a_n, w5, w6, w7;
    wire w8, w9;

    and  g0 (w0, a, b, cin);
    not  g1 (b_n, b);
    not  g2 (cin_n, cin);
    and  g3 (w3, a, b_n, cin_n);
    not  g4 (a_n, a);
    and  g5 (w5, a_n, b, cin_n);
    and  g6 (w6, a_n, b_n, cin);
    or   g7 (sum, w0, w3, w5, w6);
    and  g8 (w7, a, b);
    and  g9 (w8, a, cin);
    and  g10 (w9, b, cin);
    or   g11 (cout, w7, w8, w9);

endmodule
